// Original procedural illustrations. Their motion is decorative, never observed data.
let sequence = 0;
const palettes = [
  ['#16141d','#8c83a5','#e5edf4'], ['#142124','#6f9caa','#d8eced'],
  ['#21172d','#a281d8','#eee5ff'], ['#292018','#bf8d5e','#f6e3ca'],
  ['#191c2d','#7f8ec4','#e0e5fa'], ['#142125','#8ea6b8','#e9f0f5'],
  ['#1d2721','#90ad9b','#e1eee3'], ['#261b29','#ba90c6','#f4e4f9']
];

export function createReelArt(index = 0) {
  const kind = ((Math.trunc(Number(index) || 0) % 8) + 8) % 8;
  const [dark, mid, light] = palettes[kind];
  const id = `pulse-art-${sequence++}`;
  const gold = `url(#${id}-gold)`, soft = `url(#${id}-soft)`, face = `url(#${id}-face)`;
  const cube = (x,y,s,delay=0) => `<g transform="translate(${x} ${y})"><g class="art-voxel" style="--art-delay:${delay}s"><path d="M0 ${-s/2} ${s} 0 0 ${s/2} ${-s} 0Z" fill="${gold}"/><path d="M${-s} 0 0 ${s/2} 0 ${s*1.5} ${-s} ${s}Z" fill="${mid}"/><path d="M0 ${s/2} ${s} 0 ${s} ${s} 0 ${s*1.5}Z" fill="${dark}"/><path d="M${-s} 0 0 ${s/2} ${s} 0M0 ${s/2}V${s*1.5}" fill="none" stroke="${light}" stroke-opacity=".38"/></g></g>`;
  const chip = (x,y,r,delay=0) => `<g transform="translate(${x} ${y})"><g class="art-chip-float" style="--art-delay:${delay}s"><ellipse cy="7" rx="${r}" ry="${r*.45}" fill="${dark}" stroke="${mid}" stroke-width="4"/><ellipse rx="${r}" ry="${r*.45}" fill="${gold}"/><ellipse rx="${r*.73}" ry="${r*.32}" fill="${dark}" stroke="${light}" stroke-width="1"/><ellipse class="art-chip-rim" rx="${r*.87}" ry="${r*.38}" fill="none" stroke="${dark}" stroke-width="4" stroke-dasharray="5 9"/><path d="M0 -9 8 0 0 9 -8 0Z" fill="${gold}"/></g></g>`;
  const backgrounds = `<ellipse cx="110" cy="160" rx="76" ry="13" fill="#170e20" opacity=".3"/><circle cx="110" cy="87" r="68" fill="none" stroke="${light}" stroke-opacity=".14"/><circle cx="110" cy="87" r="84" fill="none" stroke="${light}" stroke-opacity=".06"/>`;
  const artworks = [
    // Casino: hovering chip stack and a turning faceted diamond.
    `${chip(103,139,47,-1.2)}${chip(103,120,43,-.7)}${chip(103,101,39,-.2)}<g transform="translate(115 50)"><g class="art-gem-turn"><path d="M0 -27 27 0 0 35 -27 0Z" fill="${gold}"/><path d="M0 -27V35L-27 0Z" fill="${mid}"/><path d="M0 -27 10 0 0 35 -10 0Z" fill="${light}" opacity=".65"/><path d="M-27 0H27" stroke="${light}" stroke-opacity=".5"/></g></g>`,
    // Dashboard: a luminous architectural skyline, deliberately nonnumeric.
    `<g transform="translate(34 119)"><path d="m0 15 70 32 94-45-70-31Z" fill="${dark}" stroke="${mid}" stroke-opacity=".4"/></g>${[0,1,2,3].map((v)=>`<g transform="translate(${55+v*35} ${127-v*8})"><g class="art-column" style="--art-delay:${-v*.7}s"><path d="M-14 0V-${42+v*9}L0 -${49+v*9} 14 -${42+v*9}V0L0 7Z" fill="${soft}"/><path d="M0 7V-${35+v*9}L14 -${42+v*9}V0Z" fill="${dark}" opacity=".6"/><path d="M-14 -${42+v*9} 0 -${49+v*9} 14 -${42+v*9} 0 -${35+v*9}Z" fill="${gold}"/><path d="M-8 -${28+v*9}V-7" stroke="${light}" opacity=".5"/></g></g>`).join('')}<path class="art-path-light" d="M35 135 80 110 117 125 180 82" fill="none" stroke="${light}" stroke-width="2" stroke-dasharray="7 10"/>`,
    // Dataset: records orbit an isometric cube.
    `<g class="art-grid-drift"><path d="M27 56 110 14 193 56 110 98ZM27 85 110 43 193 85 110 127ZM27 114 110 72 193 114 110 156ZM55 42V127M82 28V141M138 28V141M166 42V127" fill="none" stroke="${light}" stroke-width=".75" opacity=".28"/></g>${cube(110,77,32,-.3)}${[[42,75],[167,58],[174,126],[58,137]].map(([x,y],i)=>`<g transform="translate(${x} ${y})"><g class="art-record" style="--art-delay:${-i}s"><rect x="-13" y="-10" width="26" height="20" rx="4" fill="${soft}" stroke="${light}" stroke-opacity=".4"/><path d="M-7 -3H7M-7 3H3" stroke="${dark}" stroke-width="2"/></g></g>`).join('')}`,
    // House Edge: cascading coins with staggered vertical motion.
    `${[0,1,2,3,4].map((v)=>`<g transform="translate(${45+v*33} ${75+(v%2)*39})"><g class="art-coin-fall" style="--art-delay:${-v*.85}s"><ellipse cx="3" cy="4" rx="20" ry="26" fill="${dark}" stroke="${mid}" stroke-width="3"/><ellipse rx="20" ry="26" fill="${gold}"/><ellipse rx="14" ry="20" fill="none" stroke="${dark}" stroke-opacity=".5"/><path d="M0 -10 8 0 0 10 -8 0Z" fill="${dark}" opacity=".7"/><path d="M-11 -17Q0 -24 10 -16" fill="none" stroke="#fff3d8" opacity=".7"/></g></g>`).join('')}`,
    // Heads Up: illustrated card fan and poker suit orbit.
    `<g transform="translate(110 90)"><g class="art-poker-fan"><g transform="rotate(-24)"><rect x="-40" y="-45" width="63" height="88" rx="8" fill="${mid}" stroke="${light}" stroke-opacity=".5"/><rect x="-33" y="-38" width="49" height="74" rx="5" fill="none" stroke="${dark}" opacity=".35"/></g><g transform="rotate(14)"><rect x="-21" y="-42" width="63" height="88" rx="8" fill="${gold}"/><path d="M10 -17C-17 4 -6 15 5 9L1 23H19L15 9C27 15 38 4 10 -17Z" fill="${dark}"/><path d="M-11 -29H-4M-11 -24H-4M25 28H32M25 33H32" stroke="${mid}" stroke-width="2"/></g></g><g class="art-suit-orbit"><path d="M0 -78 8 -67 0 -56 -8 -67Z" fill="${gold}"/><circle cx="65" cy="15" r="6" fill="${mid}"/><path d="M-52 45C-69 32-68 55-52 59C-36 55-35 32-52 45Z" fill="${light}"/></g></g>`,
    // Highway: perspective ribbons, moving lane markers and light packets.
    `<path d="M18 181 77 80Q90 60 97 0H129Q131 61 143 80L205 181Z" fill="${dark}"/><path d="M18 181 77 80Q90 60 97 0M205 181 143 80Q131 61 129 0" fill="none" stroke="${gold}" stroke-width="3"/><path d="M56 181 94 80Q103 55 107 0M167 181 127 80Q118 55 118 0" fill="none" stroke="${mid}" stroke-width="1"/><path class="art-highway-lanes" d="M111 0V65Q111 91 112 181" fill="none" stroke="${light}" stroke-width="3" stroke-dasharray="9 13"/><g class="art-highway-lights"><path d="M61 147 79 115M142 112 160 146" stroke="${light}" stroke-width="5" stroke-linecap="round"/><path d="M61 147 79 115M142 112 160 146" stroke="#fff5df" stroke-width="1"/></g>${[0,1,2].map(v=>`<path d="M${27-v*7} ${89+v*27}H${60-v*13}M${158+v*13} ${89+v*27}H${194+v*7}" stroke="${mid}" stroke-opacity=".4"/>`).join('')}`,
    // HEB: sculptural leaves and seeds rotating around an organic center.
    `<g transform="translate(110 91)"><g class="art-botanical-orbit">${[0,1,2,3,4,5].map(v=>`<g transform="rotate(${v*60})"><path d="M0 -22C-38 -40 -17 -83 0 -70C24 -58 24 -36 0 -22Z" fill="${v%2?gold:soft}" stroke="${light}" stroke-opacity=".3"/><path d="M0 -23Q-8 -43 0 -66" fill="none" stroke="${dark}" stroke-width="1.2" opacity=".4"/></g>`).join('')}</g><g class="art-seed-breathe"><ellipse rx="22" ry="27" fill="${gold}"/><path d="M0 -19Q-12 0 0 20Q12 0 0 -19Z" fill="${dark}" opacity=".42"/><path d="M-10 -16Q-17 -9-16 0" stroke="#fff3d2" fill="none" stroke-width="2" opacity=".7"/></g></g>`,
    // Databricks: stacked isometric blocks with offset motion.
    `${cube(78,112,28,-.6)}${cube(138,112,28,-1.6)}${cube(108,90,28,-1.1)}${cube(78,64,28,-2.1)}${cube(138,64,28,-.1)}${cube(108,42,28,-1.6)}<path class="art-path-light" d="M32 140 110 178 188 140" fill="none" stroke="${light}" stroke-width="1.5" stroke-dasharray="3 9"/>`
  ];
  const wrapper = document.createElement('div');
  wrapper.className = `reel-card-art reel-art-${kind}`;
  wrapper.setAttribute('aria-hidden','true');
  wrapper.innerHTML = `<svg viewBox="0 0 220 180" xmlns="http://www.w3.org/2000/svg" focusable="false" preserveAspectRatio="xMidYMid slice"><defs><radialGradient id="${id}-bg" cx=".35" cy=".2" r=".95"><stop stop-color="${mid}"/><stop offset=".65" stop-color="${dark}"/><stop offset="1" stop-color="#231523"/></radialGradient><linearGradient id="${id}-gold" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#fff2d3"/><stop offset=".25" stop-color="${light}"/><stop offset=".58" stop-color="${mid}"/><stop offset=".82" stop-color="${light}"/><stop offset="1" stop-color="${mid}"/></linearGradient><linearGradient id="${id}-soft" x1="0" y1="0" x2="1" y2="1"><stop stop-color="${light}"/><stop offset="1" stop-color="${mid}"/></linearGradient><linearGradient id="${id}-face"><stop stop-color="${mid}"/><stop offset="1" stop-color="${dark}"/></linearGradient></defs><rect width="220" height="180" fill="url(#${id}-bg)"/><g opacity=".18" stroke="${light}" stroke-width=".5"><path d="M0 30H220M0 60H220M0 90H220M0 120H220M0 150H220M30 0V180M70 0V180M110 0V180M150 0V180M190 0V180"/></g>${backgrounds}<g class="art-scene">${artworks[kind]}</g><g fill="${light}" opacity=".7"><circle class="art-spark" cx="32" cy="38" r="1.8"/><circle class="art-spark" style="--art-delay:-2s" cx="181" cy="37" r="1.2"/><path d="M184 151h7m-3.5-3.5v7" stroke="${light}" stroke-width=".8"/></g></svg>`;
  return wrapper;
}
